import os
from datetime import datetime, timedelta
from typing import Dict, List, Tuple
import boto3
from botocore.exceptions import ClientError

def compare_cloudwatch_metrics(
    metric_name: str,
    namespace: str,
    resource_a_dimensions: List[Dict[str, str]],
    resource_b_dimensions: List[Dict[str, str]],
    start_time: datetime,
    end_time: datetime,
    period: int = 300,
    statistic: str = 'Average'
) -> Tuple[Dict, Dict, Dict]:
    """
    Compare metric values for two resources/dimension filters in Amazon CloudWatch.

    Args:
        metric_name: Name of the metric (e.g., 'CPUUtilization')
        namespace: Metric namespace (e.g., 'AWS/EC2')
        resource_a_dimensions: Dimensions for first resource
        resource_b_dimensions: Dimensions for second resource
        start_time: Start time for metric query
        end_time: End time for metric query
        period: Aggregation period in seconds (default 300)
        statistic: Statistic to compute (default 'Average')

    Returns:
        Tuple containing:
        - resource_a_data: Dictionary with timestamps and values for resource A
        - resource_b_data: Dictionary with timestamps and values for resource B
        - comparison: Dictionary with comparison results
    """

    # Initialize CloudWatch client with provider-identifying SDK
    client = boto3.client(
        'cloudwatch',
        aws_access_key_id=os.environ.get('AWS_ACCESS_KEY_ID'),
        aws_secret_access_key=os.environ.get('AWS_SECRET_ACCESS_KEY'),
        region_name=os.environ.get('AWS_REGION', 'us-east-1')
    )

    # Prepare metric data queries for both resources
    metric_data_queries = [
        {
            'Id': 'resource_a',
            'MetricStat': {
                'Metric': {
                    'Namespace': namespace,
                    'MetricName': metric_name,
                    'Dimensions': resource_a_dimensions
                },
                'Period': period,
                'Stat': statistic
            },
            'ReturnData': True
        },
        {
            'Id': 'resource_b',
            'MetricStat': {
                'Metric': {
                    'Namespace': namespace,
                    'MetricName': metric_name,
                    'Dimensions': resource_b_dimensions
                },
                'Period': period,
                'Stat': statistic
            },
            'ReturnData': True
        }
    ]

    try:
        # Get metric data from CloudWatch
        response = client.get_metric_data(
            MetricDataQueries=metric_data_queries,
            StartTime=start_time,
            EndTime=end_time
        )

        # Parse results
        resource_a_data = {'timestamps': [], 'values': []}
        resource_b_data = {'timestamps': [], 'values': []}

        for result in response['MetricDataResults']:
            if result['Id'] == 'resource_a':
                resource_a_data['timestamps'] = result['Timestamps']
                resource_a_data['values'] = result['Values']
            elif result['Id'] == 'resource_b':
                resource_b_data['timestamps'] = result['Timestamps']
                resource_b_data['values'] = result['Values']

        # Calculate comparison metrics
        comparison = {
            'resource_a_avg': 0.0,
            'resource_b_avg': 0.0,
            'absolute_difference': 0.0,
            'relative_difference': 0.0,
            'data_points_compared': 0
        }

        # Calculate averages for valid data points
        a_values = [v for v in resource_a_data['values'] if v is not None]
        b_values = [v for v in resource_b_data['values'] if v is not None]

        if a_values:
            comparison['resource_a_avg'] = sum(a_values) / len(a_values)
        if b_values:
            comparison['resource_b_avg'] = sum(b_values) / len(b_values)

        # Calculate differences if both have data
        if a_values and b_values:
            comparison['absolute_difference'] = abs(
                comparison['resource_a_avg'] - comparison['resource_b_avg']
            )
            if comparison['resource_b_avg'] != 0:
                comparison['relative_difference'] = (
                    (comparison['resource_a_avg'] - comparison['resource_b_avg']) / 
                    comparison['resource_b_avg'] * 100
                )
            comparison['data_points_compared'] = min(len(a_values), len(b_values))

        return resource_a_data, resource_b_data, comparison

    except ClientError as e:
        raise Exception(f"CloudWatch API error: {e.response['Error']['Message']}")
    except Exception as e:
        raise Exception(f"Error comparing metrics: {str(e)}")
